static inline __m128i rotr_sse(__m128i x, int n){
    return _mm_or_si128(_mm_srli_epi32(x, n), _mm_slli_epi32(x, 32-n));
}

/* 4 independent blocks, each 64 bytes, pointed by p0..p3 */
static void compress4(const uint8_t *p0, const uint8_t *p1, const uint8_t *p2, const uint8_t *p3,
                      __m128i *H){
    __m128i w[64];
    for(int i=0;i<16;i++){
        uint32_t a = ((uint32_t)p0[i*4]<<24)|((uint32_t)p0[i*4+1]<<16)|((uint32_t)p0[i*4+2]<<8)|p0[i*4+3];
        uint32_t b = ((uint32_t)p1[i*4]<<24)|((uint32_t)p1[i*4+1]<<16)|((uint32_t)p1[i*4+2]<<8)|p1[i*4+3];
        uint32_t c = ((uint32_t)p2[i*4]<<24)|((uint32_t)p2[i*4+1]<<16)|((uint32_t)p2[i*4+2]<<8)|p2[i*4+3];
        uint32_t d = ((uint32_t)p3[i*4]<<24)|((uint32_t)p3[i*4+1]<<16)|((uint32_t)p3[i*4+2]<<8)|p3[i*4+3];
        w[i] = _mm_set_epi32(d,c,b,a);
    }
    for(int i=16;i<64;i++){
        __m128i w15=w[i-15], w2=w[i-2];
        __m128i s0 = _mm_xor_si128(_mm_xor_si128(rotr_sse(w15,7), rotr_sse(w15,18)), _mm_srli_epi32(w15,3));
        __m128i s1 = _mm_xor_si128(_mm_xor_si128(rotr_sse(w2,17), rotr_sse(w2,19)), _mm_srli_epi32(w2,10));
        w[i] = _mm_add_epi32(_mm_add_epi32(w[i-16], s0), _mm_add_epi32(w[i-7], s1));
    }
    __m128i a=H[0],b=H[1],c=H[2],d=H[3],e=H[4],f=H[5],g=H[6],h=H[7];
    for(int i=0;i<64;i++){
        __m128i S1 = _mm_xor_si128(_mm_xor_si128(rotr_sse(e,6), rotr_sse(e,11)), rotr_sse(e,25));
        __m128i ch = _mm_xor_si128(_mm_and_si128(e,f), _mm_andnot_si128(e,g));
        __m128i t1 = _mm_add_epi32(h, _mm_add_epi32(S1, _mm_add_epi32(ch, _mm_add_epi32(_mm_set1_epi32(Kc[i]), w[i]))));
        __m128i S0 = _mm_xor_si128(_mm_xor_si128(rotr_sse(a,2), rotr_sse(a,13)), rotr_sse(a,22));
        __m128i maj = _mm_xor_si128(_mm_xor_si128(_mm_and_si128(a,b), _mm_and_si128(a,c)), _mm_and_si128(b,c));
        __m128i t2 = _mm_add_epi32(S0, maj);
        h=g; g=f; f=e; e=_mm_add_epi32(d,t1); d=c; c=b; b=a; a=_mm_add_epi32(t1,t2);
    }
    H[0]=_mm_add_epi32(H[0],a); H[1]=_mm_add_epi32(H[1],b); H[2]=_mm_add_epi32(H[2],c); H[3]=_mm_add_epi32(H[3],d);
    H[4]=_mm_add_epi32(H[4],e); H[5]=_mm_add_epi32(H[5],f); H[6]=_mm_add_epi32(H[6],g); H[7]=_mm_add_epi32(H[7],h);
}

int main(){
    size_t len = 20480000; /* divisible by 256 */
    uint8_t *data = aligned_alloc(64, len);
    memset(data, 0x5a, len);
    size_t groups = len/256;
    __m128i H[8];
    uint32_t iv[8]={0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
    clock_t t0=clock();
    int N=3;
    volatile uint32_t sink=0;
    for(int n=0;n<N;n++){
        for(int i=0;i<8;i++) H[i]=_mm_set1_epi32(iv[i]);
        /* NOTE: this re-inits every group so it's 4 independent single-block hashes,
           which overestimates vs chained. To measure chained throughput we should NOT reinit.
           Chained single stream can't use 4-way. This measures 4-way independent throughput. */
        for(size_t g=0; g<groups; g++){
            for(int i=0;i<8;i++) H[i]=_mm_set1_epi32(iv[i]);
            const uint8_t *base = data + g*256;
            compress4(base, base+64, base+128, base+192, H);
        }
        sink ^= _mm_extract_epi32(H[0],0);
    }
    clock_t t1=clock();
    SHA256_CTX ctx; uint8_t out[32];
    for(int n=0;n<N;n++){ SHA256_Init(&ctx); SHA256_Update(&ctx,data,len); SHA256_Final(out,&ctx); sink^=out[0]; }
    clock_t t2=clock();
    printf("avx4 %.4f s   ossl %.4f s   sink %u\n",
        (double)(t1-t0)/CLOCKS_PER_SEC/N, (double)(t2-t1)/CLOCKS_PER_SEC/N, sink);
    return 0;
}
